 function formatBlock(tag:string){if(readOnly)return;if(tag==='blockquote'){runEngineStructure('blockquote');return}const success=runEngineStructure('formatBlock',tag);if(success){setFormat(/^h[1-6]$/.test(tag)?'Título '+tag[1]:'Normal');lastRepeatable.current={command:'formatBlock',value:tag}}}
