 function insertImageFile(file?:File){if(!file)return;if(!/^image\/(png|jpeg|gif|webp)$/i.test(file.type)){setImportError('Formato de imagem não suportado. Use PNG, JPEG, GIF ou WebP.');return}if(file.size>10*1024*1024){setImportError('A imagem excede o limite de 10 MB.');return}const reader=new FileReader();reader.onerror=()=>setImportError('Não foi possível ler a imagem selecionada.');reader.onload=()=>{const result=reader.result;if(typeof result!=='string'||!/^data:image\/(png|jpeg|gif|webp);base64,/i.test(result)){setImportError('O arquivo selecionado não é uma imagem válida.');return}setImportError('');exec('insertImage',result)};reader.readAsDataURL(file)}
