 function insertShape(){const kind=window.prompt('Forma para inserir: retângulo, círculo ou triângulo','retângulo');if(!kind)return;const html=kind.toLowerCase().includes('círc')?'<span style="display:inline-block;width:90px;height:60px;border:2px solid #2563eb;border-radius:50%;vertical-align:middle;margin:4px"></span>':kind.toLowerCase().includes('tri')?'<span style="display:inline-block;width:0;height:0;border-left:42px solid transparent;border-right:42px solid transparent;border-bottom:72px solid #2563eb;vertical-align:middle;margin:4px"></span>':'<span style="display:inline-block;width:110px;height:60px;border:2px solid #2563eb;vertical-align:middle;margin:4px"></span>';insertHtmlFragment(html+' ')}
