 function showDetailedStats(){const text=plainText(readEditorHtml()||content);const words=text.trim().split(/\s+/).filter(Boolean);const paragraphs=text.split(/\n+/).filter(x=>x.trim()).length;const chars=text.length;const charsNoSpaces=text.replace(/\s/g,'').length;const sentences=(text.match(/[.!?]+(?=\s|$)/g)||[]).length;const pages=Math.max(1,Math.ceil(words.length/500));window.alert('Estatísticas do documento\n\nPalavras: '+words.length+'\nCaracteres (com espaços): '+chars+'\nCaracteres (sem espaços): '+charsNoSpaces+'\nParágrafos estimados: '+paragraphs+'\nFrases estimadas: '+sentences+'\nPáginas estimadas (500 palavras/página): '+pages)}
