 function checkAccessibility(){const editor=editorRef.current;if(!editor)return;const issues:string[]=[];if(!editor.querySelector('h1,h2,h3'))issues.push('Não há títulos estruturados (H1–H3).');editor.querySelectorAll('img').forEach((img,i)=>{if(!img.getAttribute('alt'))issues.push('Imagem '+(i+1)+' sem texto alternativo.')});editor.querySelectorAll('a').forEach((a,i)=>{if(!a.textContent?.trim())issues.push('Link '+(i+1)+' sem texto descritivo.')});if(!issues.length)issues.push('Nenhum problema básico de acessibilidade detectado.');window.alert('Verificação básica de acessibilidade:\n\n• '+issues.join('\n• '))}
