 function downloadCurrent(formatOverride?:string){const ext=(formatOverride||type||'html').replace(/[^a-z0-9]/gi,'')||'html';const html=sanitizeHtml(readEditorHtml()||content);if(ext==='nsx'){try{const engine=nexusEngineRef.current;if(!engine)throw new Error('O motor Nexus ainda não está pronto.');syncNexusEngine(engine,html,name);const beforeNormalization=engine.getDocument();engine.normalize();if(engine.getDocument()!==beforeNormalization){writeEditorHtml(htmlFromNexusDocument(engine.getDocument()));paginateEditor()}const saved=engine.save();if(!saved.ok)throw new Error(saved.error.message);downloadBlob(new Blob([saved.value],{type:'application/vnd.korczak.nexus+json;charset=utf-8'}),safeFilename(name)+'.nsx')}catch(error){setImportError(error instanceof Error?error.message:'Não foi possível exportar o arquivo NSX.')}return}if(ext==='docx'){void exportDocx();return}if(ext==='pdf'){printPdf();return}if(ext==='html'){exportHtml();return}if(ext==='md'||ext==='markdown'){downloadBlob(new Blob([htmlToMarkdown(html)],{type:'text/markdown;charset=utf-8'}),safeFilename(name)+'.md');return}if(ext==='rtf'){downloadBlob(new Blob([htmlToRtf(html)],{type:'application/rtf;charset=utf-8'}),safeFilename(name)+'.rtf');return}const engine=nexusEngineRef.current;downloadBlob(new Blob([engine?exportPlainText(engine.getDocument()):plainText(html)],{type:'text/plain;charset=utf-8'}),safeFilename(name)+'.txt')}
