 function showDocumentProperties(){const engine=nexusEngineRef.current;if(!engine)return;const metadata=engine.getDocument().metadata;window.alert('Propriedades do documento\\n\\nNome: '+name+'\\nAutor: '+String(metadata.author??'Não informado')+'\\nTipo: '+type.toUpperCase()+'\\nCriado em: '+new Date(document.created_at).toLocaleString('pt-BR')+'\\nÚltima alteração: '+new Date(document.updated_at).toLocaleString('pt-BR')+'\\nVersão atual: '+(versions[0]?.version_number||'1')+'\\nPalavras: '+plainText(sanitizeHtml(readEditorHtml()||content)).trim().split(/\\s+/).filter(Boolean).length+'\\nCaracteres: '+plainText(sanitizeHtml(readEditorHtml()||content)).length);const author=window.prompt('Autor do documento (deixe vazio para limpar):',String(metadata.author??''));if(author===null)return;const result=engine.exec([setMetadata({key:'author',value:author.trim()})],{group:'structural'});if(!result.ok){setMessage(result.error.message);return}setState('dirty');setMessage('Autor atualizado no motor Nexus. Exporte em .nsx para preservar este metadado no arquivo.')}
 function compareDocumentVersion(){if(!versions.length){window.alert('Não há versões disponíveis para comparar.');return}const choices=versions.map(v=>'Versão '+v.version_number+' — '+new Date(v.created_at).toLocaleString('pt-BR')).join('\\n');const picked=window.prompt('Digite o número da versão para comparar com o documento atual:\\n'+choices,String(versions[1]?.version_number??versions[0].version_number));if(picked===null)return;const version=versions.find(v=>String(v.version_number)===picked.trim());if(!version){window.alert('Número de versão inválido.');return}const oldText=plainText(stripLayoutMetadata(version.content||''));const newText=plainText(sanitizeHtml(readEditorHtml()||content));const oldWords=oldText.trim().split(/\\s+/).filter(Boolean),newWords=newText.trim().split(/\\s+/).filter(Boolean);let common=0;const counts=new Map<string,number>();oldWords.forEach(w=>counts.set(w,(counts.get(w)||0)+1));newWords.forEach(w=>{const n=counts.get(w)||0;if(n>0){common++;counts.set(w,n-1)}});window.alert('Comparação com a versão '+version.version_number+'\\n\\nVersão selecionada: '+oldWords.length+' palavras\\nDocumento atual: '+newWords.length+' palavras\\nPalavras em comum (aprox.): '+common+'\\nPalavras adicionadas (aprox.): '+Math.max(0,newWords.length-common)+'\\nPalavras removidas (aprox.): '+Math.max(0,oldWords.length-common)+'\\n\\nEsta é uma comparação resumida por palavras, não uma marcação visual das alterações.')}
 async function exportPasswordProtectedCopy(){const password=window.prompt('Defina uma senha para proteger uma cópia exportada deste documento (mínimo 8 caracteres):');if(password===null)return;if(password.length<8){window.alert('Use uma senha com pelo menos 8 caracteres.');return}try{if(!window.crypto?.subtle)throw new Error('Criptografia segura não disponível neste navegador.');const salt=window.crypto.getRandomValues(new Uint8Array(16));const iv=window.crypto.getRandomValues(new Uint8Array(12));const material=await window.crypto.subtle.importKey('raw',new TextEncoder().encode(password),'PBKDF2',false,['deriveKey']);const key=await window.crypto.subtle.deriveKey({name:'PBKDF2',salt,iterations:250000,hash:'SHA-256'},material,{name:'AES-GCM',length:256},false,['encrypt']);const payload=JSON.stringify({name,type,content:sanitizeHtml(readEditorHtml()||content),layout:{pageSize,orientation,margin,headerText,footerText,footerAlign,showPageNumbers,fontFamily}});const encrypted=await window.crypto.subtle.encrypt({name:'AES-GCM',iv},key,new TextEncoder().encode(payload));const toBase64=(bytes:Uint8Array)=>window.btoa(String.fromCharCode(...bytes));downloadBlob(new Blob([JSON.stringify({format:'korczak-nexus-encrypted-v1',algorithm:'AES-GCM',kdf:'PBKDF2-SHA-256',iterations:250000,salt:toBase64(salt),iv:toBase64(iv),data:toBase64(new Uint8Array(encrypted))},null,2)],{type:'application/json;charset=utf-8'}),safeFilename(name)+'.nexus-protegido.json');window.alert('Cópia criptografada exportada. A senha protege este arquivo exportado; o documento armazenado no Nexus não foi alterado nem criptografado no servidor.')}catch(error){window.alert(error instanceof Error?error.message:'Não foi possível proteger a cópia do documento.')}}
 function runFind(){if(!findText){setFindMessage('Digite um termo para pesquisar.');return}if(!editorRef.current)return;const result=findTextMatches(editorRef.current,findText);setFindMessage(result.count?result.count+' ocorrência(s) no documento.':'Nenhuma ocorrência encontrada.');if(result.ranges.length){const index=findCursor%result.ranges.length;const range=result.ranges[index];setFindCursor(index+1);const selection=window.getSelection();selection?.removeAllRanges();selection?.addRange(range);(range.startContainer.parentElement as HTMLElement|null)?.scrollIntoView({behavior:'smooth',block:'center'})}}
