 async function clipboardAction(action:'cut'|'copy'|'paste'|'paste-plain'){if(readOnly&&action!=='copy'){setMessage('Desative Somente leitura para editar.');return}const selection=window.getSelection();const editor=editorRef.current;if(action==='copy'||action==='cut'){if(!selection||selection.isCollapsed||!editor?.contains(selection.anchorNode)){setMessage('Selecione o conteúdo primeiro.');return}const text=selection.toString();try{await navigator.clipboard.writeText(text)}catch{if(!window.document.execCommand(action)){setMessage('O navegador não permitiu acessar a área de transferência.');return}}if(action==='cut'){exec('insertText','')}setMessage(action==='cut'?'Conteúdo recortado.':'Conteúdo copiado.');return}if(action==='paste-plain'||action==='paste'){try{const clip=await navigator.clipboard.read();let text='';let html='';for(const item of clip){if(action==='paste'&&item.types.includes('text/html')){html=await(await item.getType('text/html')).text();break}if(item.types.includes('text/plain'))text=await(await item.getType('text/plain')).text()}const value=action==='paste'&&html?sanitizeHtml(html):text;if(!value){setMessage('A área de transferência não contém texto compatível.');return}if(action==='paste-plain'||!html){exec('insertText',value);setMessage('Texto inserido pelo motor Nexus sem formatação.');return}focusEditor();window.document.execCommand('insertHTML',false,sanitizeHtml(value));syncEditor();setMessage('Conteúdo colado.')}catch{setMessage('O navegador bloqueou a leitura da área de transferência. Use Ctrl/Cmd+'+(action==='paste'?'V':'Shift+V')+' dentro do editor.')}}}
